const b = $input.first().json;
const x = b.ctx || {};
const risk = { S7: ['심각', 95, 0xE74C3C], S1: ['높음', 80, 0xE67E22], S4: ['높음', 80, 0xE67E22], S10: ['높음', 75, 0xE67E22], S12: ['높음', 70, 0xE67E22], S8: ['보통', 55, 0xF1C40F], H1: ['보통', 50, 0xF1C40F] };
const [severity, risk_score, color] = risk[b.case_id] || ['낮음', 25, 0x3498DB];
const icon = { 심각: '🚨', 높음: '⚠️', 보통: '🟡', 낮음: '🔵' }[severity];
const dashboard_url = x.dashboard_url || 'http://127.0.0.1:8089';
const status = b.level === 'error' ? '담당자 확인 필요' : /원복/.test(b.title || '') ? '복구 완료' : '자동 차단 처리 중';
const embed = {
  title: `${icon} 위험도 ${risk_score}% · [${b.case_id || '-'}] ${b.title || '보안 인시던트'}`,
  description: `**위험도: ${risk_score}% (${severity})**
[🔗 보안 대시보드 열기](${dashboard_url})`,
  color,
  fields: [
    { name: '발생 IP', value: b.src_ip || '-', inline: true },
    { name: '인시던트 티켓', value: b.ticket_id || '-', inline: true },
    { name: '처리 상태', value: status, inline: false }
  ],
  footer: { text: `해담 SOAR · n8n 실행 ${$execution.id}` },
  timestamp: new Date().toISOString()
};
return [{ json: { content: `${icon} ${severity} 위험도 ${risk_score}% · ${b.ticket_id || '티켓 생성 중'}`, embed, ctx: x } }];

const j = $input.first().json;
const failed = !!(j.error || (j.message && /credential|webhook|ENOTFOUND|\b4\d\d\b/i.test(String(j.message))));
return [{ json: { sent: !failed, error: failed ? String((j.error && j.error.message) || j.message || j.error) : null, ctx: $('Discord 알림 카드').first().json.ctx } }];
